package com.hospital.smartqueue.doctor.scheduling.domain;
import jakarta.persistence.*; import org.hibernate.annotations.UuidGenerator; import java.time.*; import java.util.*;
@Entity @Table(name="schedule_exceptions") public class ScheduleException { @Id @GeneratedValue @UuidGenerator private UUID id; @Column(name="doctor_id",nullable=false) private UUID doctorId; @Column(name="branch_id",nullable=false) private UUID branchId; @Column(name="exception_date",nullable=false) private LocalDate exceptionDate; @Version private long version; protected ScheduleException(){} public ScheduleException(UUID d,UUID b,LocalDate date){doctorId=d;branchId=b;exceptionDate=date;} public UUID getId(){return id;} public LocalDate getExceptionDate(){return exceptionDate;} public long getVersion(){return version;} public void replace(LocalDate date){exceptionDate=date;} }
